package io.github.jasper.monitoring.api.management;
import io.github.jasper.monitoring.api.management.command.*; import io.github.jasper.monitoring.api.management.model.ControlView; import io.github.jasper.monitoring.api.management.query.*;
/** Control approval boundary. Authorization precedes access; state/audit writes are transactional and host effects occur after commit. */
public interface ControlManagementService { /** Requires CONTROL_READ before bounded time-range query; attempts are sanitized. */ ManagementPage<ControlView> search(ManagementActor actor, ControlQuery query); /** Requires CONTROL_READ before lookup. */ ControlView get(ManagementActor actor, String id); /** Requires CONTROL_APPROVE with expectedVersion/idempotency key; reserves PENDING before external effect. */ ControlView approve(ManagementActor actor, ControlApprovalCommand command); /** Requires CONTROL_REJECT with expectedVersion/idempotency key and bounded reason. */ ControlView reject(ManagementActor actor, ControlRejectionCommand command); /** Requires CONTROL_RETRY with expectedVersion/idempotency key; only FAILED controls are accepted. */ ControlView retryFailed(ManagementActor actor, ControlRetryCommand command); }
